codeExample.bad:
/* Justified body text with single line-height and no user override path.
   Justification creates uneven word spacing, and 1.0 line-height gives
   readers no visual breathing room between lines. */
.article-body p {
  text-align: justify;
  line-height: 1;
  margin-bottom: 0.5em;
  color: #222;
  background: #fff;
}

codeExample.good:
/* Ragged-right alignment, generous line and paragraph spacing, and a
   max character width. Colors are left to user/browser style sheets
   to override rather than hard-coded as !important. */
.article-body {
  max-width: 80ch;
}

.article-body p {
  text-align: left;
  line-height: 1.5;
  margin-bottom: 2.25em; /* 1.5x the 1.5 line-height, in em units */
}
